<?php
/**
 * Plugin Name: ZARP WhatsApp OTP for WooCommerce
 * Description: Checkout verification and passwordless customer login via Interakt WhatsApp authentication templates.
 * Version: 1.1.7
 * Requires PHP: 7.4
 * Requires Plugins: woocommerce
 */
defined( 'ABSPATH' ) || exit;

final class ZARP_WhatsApp_OTP {
	const OPTION = 'zarp_whatsapp_otp_settings';
	const STATUS_OPTION = 'zarp_whatsapp_otp_connection_status';
	const ACTIVITY_OPTION = 'zarp_whatsapp_otp_activity_log';
	const TABLE = 'zarp_otp_verifications';
	private static $instance;
	public static function instance() { return self::$instance ?: self::$instance = new self(); }
	private function __construct() {
		add_action( 'wp_enqueue_scripts', array( $this, 'assets' ) );
		add_action( 'woocommerce_review_order_before_submit', array( $this, 'checkout_ui' ), 5 );
		add_filter( 'woocommerce_checkout_get_value', array( $this, 'checkout_phone_value' ), 10, 2 );
		add_action( 'woocommerce_after_checkout_validation', array( $this, 'guard_checkout' ), 10, 2 );
		add_action( 'woocommerce_checkout_create_order', array( $this, 'save_order_meta' ), 10, 2 );
		add_action( 'woocommerce_before_customer_login_form', array( $this, 'login_ui' ), 1 );
		add_action( 'woocommerce_login_form_start', array( $this, 'header_login_ui' ), 1 );
		add_filter( 'the_content', array( $this, 'account_content_fallback' ), 20 );
		add_action( 'wp_ajax_zarp_otp', array( $this, 'ajax' ) ); add_action( 'wp_ajax_nopriv_zarp_otp', array( $this, 'ajax' ) );
		add_action( 'admin_menu', array( $this, 'settings_page' ) ); add_action( 'admin_init', array( $this, 'register_settings' ) );
		add_action( 'admin_post_zarp_otp_download_log', array( $this, 'download_log' ) );
	}
	public static function activate() { global $wpdb; $table=$wpdb->prefix.self::TABLE; require_once ABSPATH.'wp-admin/includes/upgrade.php'; dbDelta("CREATE TABLE $table (id bigint unsigned NOT NULL AUTO_INCREMENT, phone_hash char(64) NOT NULL, purpose varchar(40) NOT NULL, session_key varchar(128) NOT NULL, otp_hash varchar(255) NOT NULL, expires_at datetime NOT NULL, attempts tinyint unsigned NOT NULL DEFAULT 0, resend_count tinyint unsigned NOT NULL DEFAULT 0, last_sent_at datetime NOT NULL, verified_at datetime NULL, status varchar(16) NOT NULL DEFAULT 'active', created_at datetime NOT NULL, PRIMARY KEY (id), KEY lookup (phone_hash,purpose,session_key,status), KEY expiry (expires_at)) {$wpdb->get_charset_collate()};"); }
	private function settings() { $s=wp_parse_args( get_option( self::OPTION, array() ), array( 'secret'=>'', 'template'=>'otp_authentication_templates', 'language'=>'en', 'expiry'=>600, 'cooldown'=>60, 'max_resends'=>3, 'max_attempts'=>5, 'cod'=>'yes', 'login'=>'yes', 'registration'=>'yes' ) );$s['expiry']=max(600,(int)$s['expiry']);return $s; }
	public function assets() { $s=$this->settings();if(!is_checkout()&&!is_account_page()&&('yes'!==$s['login']||is_user_logged_in()))return;wp_enqueue_style('zarp-otp',plugins_url('assets/otp.css',__FILE__),array(),'1.1.7');wp_enqueue_script('zarp-otp',plugins_url('assets/otp.js',__FILE__),array('jquery'),'1.1.7',true);$redirect=isset($_GET['redirect_to'])?wp_validate_redirect(wp_unslash($_GET['redirect_to']),wc_get_page_permalink('myaccount')):wc_get_page_permalink('myaccount');wp_localize_script('zarp-otp','zarpOtp',array('ajax'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('zarp_otp'),'cooldown'=>(int)$s['cooldown'],'redirect'=>esc_url_raw($redirect))); }
	private function session_key() { if ( function_exists('WC') && WC()->session ) return 'wc:'.WC()->session->get_customer_id(); return 'wp:'.wp_get_session_token(); }
	private function phone( $raw ) { $digits=preg_replace('/\D+/', '', (string) $raw); if ( strlen($digits)===10 && preg_match('/^[6-9]/',$digits) ) return array('+91',$digits); if ( substr($digits,0,2)==='91' && strlen($digits)===12 ) return array('+91',substr($digits,2)); return false; }
	private function hash_phone( $number ) { return hash_hmac('sha256',$number,wp_salt('auth')); }
	private function users_by_phone( $full ) { $national=substr($full,3);$users=get_users(array('meta_query'=>array(array('key'=>'billing_phone','value'=>array($full,$national,'91'.$national,'0'.$national),'compare'=>'IN')),'number'=>3,'fields'=>'ID'));return array_map('intval',$users); }
	private function user_by_phone( $full ) { $users=$this->users_by_phone($full);return 1===count($users)?$users[0]:0; }
	private function login_user($user_id,$redirect=''){ $user=get_user_by('id',$user_id);if(!$user)return false;wp_clear_auth_cookie();wp_set_current_user($user_id);wp_set_auth_cookie($user_id,true,is_ssl());do_action('wp_login',$user->user_login,$user);$fallback=wc_get_page_permalink('myaccount');return wp_validate_redirect($redirect,$fallback); }
	private function claim_guest_orders($user_id,$full){
		$user_id=absint($user_id);if(!$user_id||!function_exists('wc_get_orders'))return 0;
		$lock='zarp_order_claim_'.$this->hash_phone($full);$locked=add_option($lock,time(),'','no');
		if(!$locked){$lock_time=(int)get_option($lock,0);if($lock_time&&time()-$lock_time>120){delete_option($lock);$locked=add_option($lock,time(),'','no');}}
		if(!$locked){$this->log('guest_order_claim_skipped reason=locked user_id='.$user_id,$full);return 0;}
		$claimed=0;
		try{
			$ids=wc_get_orders(array('customer_id'=>0,'limit'=>500,'return'=>'ids','orderby'=>'ID','order'=>'ASC','meta_query'=>array('relation'=>'AND',array('key'=>'_zarp_whatsapp_verified','value'=>'yes','compare'=>'='),array('key'=>'_zarp_verified_phone','value'=>$full,'compare'=>'='))));
			foreach($ids as $order_id){
				$order=wc_get_order($order_id);if(!$order||(int)$order->get_customer_id()!==0)continue;
				if('yes'!==$order->get_meta('_zarp_whatsapp_verified',true))continue;
				$stored=$this->phone($order->get_meta('_zarp_verified_phone',true));if(!$stored||!hash_equals($full,$stored[0].$stored[1]))continue;
				$order->set_customer_id($user_id);$order->save();$order->add_order_note('Guest order linked to customer account after WhatsApp OTP verification.');$claimed++;
			}
			update_user_meta($user_id,'_zarp_guest_orders_claimed_at',gmdate('c'));
			do_action('zarp_whatsapp_guest_orders_claimed',$user_id,$full,$claimed);
		}catch(Throwable $e){$this->log('guest_order_claim_failed user_id='.$user_id.' error='.sanitize_text_field($e->getMessage()),$full);}finally{delete_option($lock);}
		$this->log('guest_order_claim_complete user_id='.$user_id.' linked='.$claimed,$full);return $claimed;
	}
	private function log( $event, $phone='' ) { $event=sanitize_text_field(wp_strip_all_tags((string)$event));$event=preg_replace('/(?<!\d)(?:91)?[6-9]\d{9}(?!\d)/','[masked-phone]',$event);$event=preg_replace('/(?<!\d)\d{6}(?!\d)/','[masked-code]',$event);$line=gmdate('Y-m-d H:i:s').' UTC | '.$event.($phone?' | phone='.substr($phone,0,3).'******'.substr($phone,-2):'');$entries=get_option(self::ACTIVITY_OPTION,array());if(!is_array($entries))$entries=array();$entries[]=$line;if(count($entries)>500)$entries=array_slice($entries,-500);update_option(self::ACTIVITY_OPTION,$entries,false);if(function_exists('wc_get_logger'))wc_get_logger()->info($line,array('source'=>'zarp-whatsapp-otp')); }
	public function checkout_ui() { if('yes'!==$this->settings()['cod']) return; ?><div id="zarp-cod-otp" class="zarp-otp" hidden><div class="zarp-otp-entry" hidden><p class="form-row"><label for="zarp-checkout-code"><?php esc_html_e('Enter WhatsApp OTP','zarp-otp'); ?></label><input id="zarp-checkout-code" class="input-text" inputmode="numeric" maxlength="15" autocomplete="one-time-code"></p><button type="button" class="button zarp-resend" data-purpose="checkout_verification"><?php esc_html_e('Resend OTP','zarp-otp'); ?></button></div><p class="zarp-message" role="status"></p></div><?php }
	public function checkout_phone_value($value,$input){if('billing_phone'!==$input)return $value;$phone=$this->phone($value);return $phone?$phone[1]:$value;}
	public function login_ui() { $s=$this->settings();if('yes'!==$s['login']||is_user_logged_in())return;?><section id="zarp-login-otp" class="zarp-otp woocommerce-form"><h3><?php esc_html_e('Login with WhatsApp','zarp-otp');?></h3><div class="zarp-login-phone-step"><p class="woocommerce-form-row form-row wooma-row"><label for="zarp-login-phone"><?php esc_html_e('Mobile number','zarp-otp');?></label><span class="zarp-phone-wrap"><span class="zarp-prefix">+91</span><input id="zarp-login-phone" class="woocommerce-Input input-text" inputmode="numeric" maxlength="10" autocomplete="tel-national" placeholder="9876543210"></span></p><button type="button" class="woocommerce-button button wooma-btn wooma-bg-black zarp-send"><?php esc_html_e('Continue with WhatsApp','zarp-otp');?></button></div><div class="zarp-otp-entry" hidden><p><?php esc_html_e('Enter the OTP sent to WhatsApp','zarp-otp');?></p><p class="woocommerce-form-row form-row wooma-row"><input id="zarp-login-code" class="woocommerce-Input input-text" inputmode="numeric" maxlength="6" autocomplete="one-time-code" placeholder="OTP"></p><button type="button" class="woocommerce-button button wooma-btn wooma-bg-black zarp-verify"><?php esc_html_e('Verify OTP','zarp-otp');?></button> <button type="button" class="button zarp-resend"><?php esc_html_e('Resend OTP','zarp-otp');?></button></div><div class="zarp-account" hidden><h3><?php esc_html_e('Almost there','zarp-otp');?></h3><p class="zarp-verified-phone"></p><p class="woocommerce-form-row form-row wooma-row"><label><?php esc_html_e('Name','zarp-otp');?><input class="woocommerce-Input input-text zarp-name" autocomplete="name"></label></p><p class="woocommerce-form-row form-row wooma-row"><label><?php esc_html_e('Email','zarp-otp');?><input class="woocommerce-Input input-text zarp-email" type="email" autocomplete="email"></label></p><button type="button" class="woocommerce-button button wooma-btn wooma-bg-black zarp-create"><?php esc_html_e('Create Account','zarp-otp');?></button> <button type="button" class="button zarp-restart"><?php esc_html_e('Use another number','zarp-otp');?></button></div><p class="zarp-message" role="status" aria-live="polite"></p></section><?php }
	public function ajax() { $op=sanitize_key($_POST['op']??'');$purpose=sanitize_key($_POST['purpose']??'');$this->log('AJAX request received op='.$op.' purpose='.$purpose);if(!check_ajax_referer('zarp_otp','nonce',false)){$this->log('AJAX rejected: invalid or expired nonce');wp_send_json_error(array('message'=>'The page security token expired. Refresh the page and try again.'),403);}if($purpose==='checkout_cod_verification')$purpose='checkout_verification';if(!in_array($purpose,array('checkout_verification','account_login'),true)){$this->log('AJAX rejected: invalid purpose='.$purpose);wp_send_json_error(array('message'=>'Invalid request.'),400);}$s=$this->settings();if('account_login'===$purpose&&('yes'!==$s['login']||is_user_logged_in())){$this->log('Account authentication blocked: feature disabled or user already logged in');wp_send_json_error(array('message'=>'WhatsApp login is unavailable.'),403);}$raw=$_POST['phone']??'';$phone=$this->phone($raw);if(!$phone){$this->log('login_phone_validation failed');wp_send_json_error(array('message'=>'Please enter a valid 10-digit WhatsApp number.'),422);}$full=$phone[0].$phone[1];$this->log('AJAX validated op='.$op.' purpose='.$purpose,$full);if($op==='send'||$op==='resend')$this->send($purpose,$phone,$op==='resend');if($op==='verify')$this->verify($purpose,$full,sanitize_text_field($_POST['code']??''),sanitize_text_field($_POST['redirect']??''));if($op==='create'){if('yes'!==$s['registration'])wp_send_json_error(array('message'=>'WhatsApp registration is currently disabled.'),403);$this->create_account($full,sanitize_text_field($_POST['redirect']??''));}$this->log('AJAX rejected: invalid operation='.$op,$full);wp_send_json_error(array('message'=>'Invalid request.'),400); }
	private function row($purpose,$full,$status='active') { global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}".self::TABLE." WHERE phone_hash=%s AND purpose=%s AND status=%s ORDER BY id DESC LIMIT 1",$this->hash_phone($full),$purpose,$status)); }
	private function row_by_id($id,$purpose,$full,$status) { global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}".self::TABLE." WHERE id=%d AND phone_hash=%s AND purpose=%s AND session_key=%s AND status=%s LIMIT 1",$id,$this->hash_phone($full),$purpose,$this->session_key(),$status)); }
	private function send($purpose,$phone,$resend) { global $wpdb;$s=$this->settings();$full=$phone[0].$phone[1];$phone_hash=$this->hash_phone($full);$this->log('OTP send started purpose='.$purpose.' resend='.($resend?'yes':'no').' template='.$s['template'].' language='.$s['language'],$full);if(empty($s['secret'])){$this->log('OTP send stopped: API key is missing',$full);wp_send_json_error(array('message'=>'WhatsApp OTP is not configured.'),503);}$old=$this->row($purpose,$full);$now=time();$last_sent=$old?strtotime($old->last_sent_at.' UTC'):0;if($old&&$now-$last_sent<(int)$s['cooldown']){$wait=(int)$s['cooldown']-($now-$last_sent);$this->log('OTP send rate-limited locally wait='.$wait.'s',$full);wp_send_json_error(array('message'=>'Please wait before requesting another OTP.','wait'=>$wait),429);}if($old&&$old->resend_count>=(int)$s['max_resends']){$this->log('OTP send stopped: resend limit reached',$full);wp_send_json_error(array('message'=>'Too many OTP requests. Please try again later.'),429);}$otp=(string)random_int(100000,999999);$button_values=new stdClass();$button_values->{'0'}=array($otp);$body=array('countryCode'=>$phone[0],'phoneNumber'=>$phone[1],'type'=>'Template','template'=>array('name'=>$s['template'],'languageCode'=>$s['language'],'bodyValues'=>array($otp),'buttonValues'=>$button_values));$api_key=preg_replace('/^Basic\s+/i','',trim($s['secret']));$this->log('Calling Interakt Send Template API auth=basic-api-key buttonValues=object',$full);$response=wp_remote_post('https://api.interakt.ai/v1/public/message/',array('timeout'=>15,'headers'=>array('Authorization'=>'Basic '.$api_key,'Content-Type'=>'application/json'),'body'=>wp_json_encode($body)));$code=is_wp_error($response)?0:(int)wp_remote_retrieve_response_code($response);$raw=is_wp_error($response)?$response->get_error_message():wp_remote_retrieve_body($response);$json=json_decode($raw,true);$detail=sanitize_text_field(wp_strip_all_tags((string)$raw));$this->log('Interakt response HTTP '.$code.($detail?' body='.substr($detail,0,500):''),$full);$accepted=$code>=200&&$code<300&&is_array($json)&&!empty($json['result']);if(!$accepted){update_option(self::STATUS_OPTION,array('ok'=>false,'time'=>time(),'http'=>$code,'message'=>$detail));wp_send_json_error(array('message'=>'Interakt rejected the OTP request. Download the activity log for the exact response.'),502);}update_option(self::STATUS_OPTION,array('ok'=>true,'time'=>time(),'http'=>$code,'message'=>sanitize_text_field($json['message']??'Request accepted'),'id'=>sanitize_text_field($json['id']??''),'key_hash'=>hash('sha256',$api_key)));$wpdb->query($wpdb->prepare("UPDATE {$wpdb->prefix}".self::TABLE." SET status='superseded' WHERE phone_hash=%s AND purpose=%s AND status='active'",$phone_hash,$purpose));$inserted=$wpdb->insert($wpdb->prefix.self::TABLE,array('phone_hash'=>$phone_hash,'purpose'=>$purpose,'session_key'=>$this->session_key(),'otp_hash'=>wp_hash_password($otp),'expires_at'=>gmdate('Y-m-d H:i:s',$now+(int)$s['expiry']),'resend_count'=>$old?(int)$old->resend_count+1:0,'last_sent_at'=>gmdate('Y-m-d H:i:s',$now),'created_at'=>gmdate('Y-m-d H:i:s',$now)));if(false===$inserted){$this->log('Interakt accepted OTP but local verification record could not be saved database_error='.$wpdb->last_error,$full);wp_send_json_error(array('message'=>'OTP was queued, but verification could not be initialized. Please contact support.'),500);}$this->log('OTP queued and local verification record saved record_id='.$wpdb->insert_id.' expires_utc='.gmdate('Y-m-d H:i:s',$now+(int)$s['expiry']).' message_id='.sanitize_text_field($json['id']??''),$full);wp_send_json_success(array('message'=>'OTP sent to WhatsApp.','cooldown'=>(int)$s['cooldown'])); }
	private function verify($purpose,$full,$code,$redirect='') { global $wpdb;$this->log('OTP verification started purpose='.$purpose,$full);$r=$this->row($purpose,$full);$s=$this->settings();if(!$r){$this->log('login_otp_verification_failed reason=record_not_found',$full);wp_send_json_error(array('message'=>'Your OTP verification session was not found. Please request a new OTP.','expired'=>true),422);}$expires=strtotime($r->expires_at.' UTC');if(!$expires||$expires<time()){$this->log('login_otp_verification_failed reason=expired record_id='.$r->id.' expires_utc='.$r->expires_at.' now_utc='.gmdate('Y-m-d H:i:s'),$full);wp_send_json_error(array('message'=>'This OTP has expired. Please request a new one.','expired'=>true),422);}if($r->attempts>=(int)$s['max_attempts']){$this->log('login_otp_verification_failed reason=attempt_limit',$full);wp_send_json_error(array('message'=>'Too many verification attempts. Please request a new OTP.'),429);}if(!preg_match('/^\d{6}$/',$code)||!wp_check_password($code,$r->otp_hash,$r->id)){$wpdb->update($wpdb->prefix.self::TABLE,array('attempts'=>(int)$r->attempts+1),array('id'=>$r->id));$this->log('login_otp_verification_failed reason=incorrect record_id='.$r->id.' attempt='.((int)$r->attempts+1),$full);wp_send_json_error(array('message'=>'The OTP is incorrect. Please try again.'),422);}$wpdb->update($wpdb->prefix.self::TABLE,array('status'=>'verified','verified_at'=>gmdate('Y-m-d H:i:s')),array('id'=>$r->id,'status'=>'active'));$this->log('login_otp_verification_success purpose='.$purpose.' record_id='.$r->id,$full);if($purpose==='checkout_verification'){WC()->session->set('zarp_checkout_verified',array('phone'=>$full,'at'=>time(),'reference'=>(int)$r->id));wp_send_json_success(array('message'=>'WhatsApp number verified. You can now place the order.','verified'=>true));}$users=$this->users_by_phone($full);if(count($users)>1){$this->log('duplicate_phone_detected count='.count($users),$full);wp_send_json_error(array('message'=>'This number is linked to multiple accounts. Please contact support.'),409);}if(1===count($users)){update_user_meta($users[0],'billing_phone',substr($full,3));update_user_meta($users[0],'zarp_whatsapp_phone_e164',$full);$claimed=$this->claim_guest_orders($users[0],$full);$target=$this->login_user($users[0],$redirect);$wpdb->update($wpdb->prefix.self::TABLE,array('status'=>'consumed'),array('id'=>$r->id,'status'=>'verified'));$this->log('passwordless_login_success user_id='.$users[0].' guest_orders_linked='.$claimed,$full);wp_send_json_success(array('message'=>$claimed?sprintf(_n('Login successful. %d guest order was added to your account.','Login successful. %d guest orders were added to your account.',$claimed,'zarp-otp'),$claimed):'Login successful. Redirecting…','redirect'=>$target));}if('yes'!==$s['registration']){$wpdb->update($wpdb->prefix.self::TABLE,array('status'=>'consumed'),array('id'=>$r->id,'status'=>'verified'));wp_send_json_error(array('message'=>'No account is linked to this number and registration is disabled.'),403);}WC()->session->set('zarp_registration_grant',array('phone'=>$full,'transaction'=>(int)$r->id,'verified_at'=>time()));$this->log('registration_started',$full);wp_send_json_success(array('create'=>true,'phone'=>'+91 '.substr($full,3),'message'=>'WhatsApp number verified. Complete your account details.')); }
	private function create_account($full,$redirect='') { global $wpdb;$grant=WC()->session->get('zarp_registration_grant');if(!$grant||!hash_equals((string)$grant['phone'],$full)||time()-(int)$grant['verified_at']>600){$this->log('registration_validation_failed reason=invalid_grant',$full);wp_send_json_error(array('message'=>'Your verified registration session expired. Please verify again.'),403);}$r=$this->row_by_id((int)$grant['transaction'],'account_login',$full,'verified');if(!$r){$this->log('registration_validation_failed reason=transaction_unavailable',$full);wp_send_json_error(array('message'=>'Your verified registration session is no longer available.'),403);}$name=trim(sanitize_text_field($_POST['name']??''));$email=sanitize_email($_POST['email']??'');if(!$name){$this->log('registration_validation_failed reason=empty_name',$full);wp_send_json_error(array('message'=>'Please enter your name.'),422);}if(!is_email($email)){$this->log('registration_validation_failed reason=invalid_email',$full);wp_send_json_error(array('message'=>'Please enter a valid email address.'),422);}if(email_exists($email)){$this->log('registration_validation_failed reason=email_exists',$full);wp_send_json_error(array('message'=>'An account already exists with this email address. Please use another email address.'),409);}$lock='zarp_registration_lock_'.$this->hash_phone($full);$locked=add_option($lock,time(),'','no');if(!$locked){$lock_time=(int)get_option($lock,0);if($lock_time&&time()-$lock_time>120){delete_option($lock);$locked=add_option($lock,time(),'','no');}}if(!$locked){$this->log('registration_lock_failed',$full);wp_send_json_error(array('message'=>'Registration is already being processed. Please wait.'),409);}if($this->users_by_phone($full)||email_exists($email)){delete_option($lock);wp_send_json_error(array('message'=>'An account already exists with these details.'),409);}$parts=preg_split('/\s+/',trim($name),2);$first=$parts[0];$last=$parts[1]??'';$national=substr($full,3);$fields=array('first_name'=>$first,'last_name'=>$last,'billing_first_name'=>$first,'billing_last_name'=>$last,'billing_phone'=>$national,'phone'=>$national,'email'=>$email,'reg_email'=>$email);$previous=array();foreach($fields as $key=>$value){$previous[$key]=array_key_exists($key,$_POST)?array(true,$_POST[$key]):array(false,null);$_POST[$key]=$value;}try{$id=wc_create_new_customer($email,'',wp_generate_password(32,true,true),array('first_name'=>$first,'last_name'=>$last));}finally{foreach($previous as $key=>$state){if($state[0])$_POST[$key]=$state[1];else unset($_POST[$key]);}}if(is_wp_error($id)){delete_option($lock);$detail=sanitize_text_field($id->get_error_message());$this->log('customer_creation_failed code='.$id->get_error_code().' message='.$detail,$full);wp_send_json_error(array('message'=>$detail?'Account creation failed: '.$detail:'We could not create your account. Please try again.'),422);}update_user_meta($id,'first_name',$first);update_user_meta($id,'last_name',$last);update_user_meta($id,'billing_first_name',$first);update_user_meta($id,'billing_last_name',$last);update_user_meta($id,'billing_phone',$national);update_user_meta($id,'zarp_whatsapp_phone_e164',$full);update_user_meta($id,'zarp_whatsapp_verified','yes');$wpdb->update($wpdb->prefix.self::TABLE,array('status'=>'consumed'),array('id'=>$r->id,'status'=>'verified'));WC()->session->__unset('zarp_registration_grant');delete_option($lock);$claimed=$this->claim_guest_orders($id,$full);$target=$this->login_user($id,$redirect);$this->log('customer_created user_id='.$id.' guest_orders_linked='.$claimed,$full);$this->log('passwordless_login_success registration=yes user_id='.$id,$full);wp_send_json_success(array('message'=>$claimed?sprintf(_n('Account created. %d guest order was added to your account.','Account created. %d guest orders were added to your account.',$claimed,'zarp-otp'),$claimed):'Account created. Redirecting…','redirect'=>$target)); }
	public function guard_checkout($data,$errors){if('yes'!==$this->settings()['cod'])return;$p=$this->phone($data['billing_phone']??'');$v=WC()->session->get('zarp_checkout_verified');if(!$p||!$v||!hash_equals($v['phone'],$p[0].$p[1])){$this->log('Checkout blocked: mobile not verified',$p?$p[0].$p[1]:'');$errors->add('zarp_checkout_otp','Please verify your WhatsApp mobile number before placing the order.');}}
	public function save_order_meta($order,$data){global $wpdb;$v=WC()->session->get('zarp_checkout_verified');if($v){$order->update_meta_data('_zarp_whatsapp_verified','yes');$order->update_meta_data('_zarp_verified_phone',$v['phone']);$order->update_meta_data('_zarp_verified_at',gmdate('c',$v['at']));$order->update_meta_data('_zarp_verification_method','whatsapp_otp');$order->update_meta_data('_zarp_otp_reference',$v['reference']);$order->add_order_note('Order verified through WhatsApp OTP.');$wpdb->update($wpdb->prefix.self::TABLE,array('status'=>'consumed'),array('id'=>(int)$v['reference'],'status'=>'verified'));WC()->session->__unset('zarp_checkout_verified');}}
	public function header_login_ui(){if(!is_account_page())$this->login_ui();}
	public function account_content_fallback($content){if(!is_admin()&&is_account_page()&&!is_user_logged_in()&&in_the_loop()&&is_main_query()&&false===strpos($content,'id="zarp-login-otp"')){ob_start();$this->login_ui();$content.=ob_get_clean();}return $content;}
	public function settings_page(){add_submenu_page('woocommerce','ZARP WhatsApp OTP','ZARP WhatsApp OTP','manage_woocommerce','zarp-whatsapp-otp',array($this,'settings_html'));}
	public function register_settings(){register_setting('zarp_otp',self::OPTION,array('sanitize_callback'=>array($this,'sanitize_settings')));}
	public function download_log(){if(!current_user_can('manage_woocommerce'))wp_die('Forbidden.');check_admin_referer('zarp_otp_download_log');$entries=get_option(self::ACTIVITY_OPTION,array());$content="ZARP WhatsApp OTP activity log\nPlugin version: 1.1.7\nSite: ".home_url('/')."\nGenerated: ".gmdate('Y-m-d H:i:s')." UTC\n\n".($entries&&is_array($entries)?implode("\n",$entries):'No activity has been recorded yet.')."\n";nocache_headers();header('Content-Type: text/plain; charset=utf-8');header('Content-Disposition: attachment; filename="zarp-whatsapp-otp-activity.log"');header('Content-Length: '.strlen($content));echo $content;exit;}
	public function sanitize_settings($v){$old=$this->settings();$secret=preg_replace('/^Basic\s+/i','',trim(isset($v['secret'])?$v['secret']:$old['secret']));if($secret){add_settings_error(self::OPTION,'zarp_key_saved','Interakt API key saved. Its connection will be confirmed when Interakt accepts the next OTP request.','success');}if($secret!==preg_replace('/^Basic\s+/i','',trim($old['secret'])))delete_option(self::STATUS_OPTION);$clean=array('secret'=>$secret,'template'=>sanitize_key(isset($v['template'])?$v['template']:'otp_authentication_templates'),'language'=>sanitize_key(isset($v['language'])?$v['language']:'en'),'expiry'=>max(600,absint(isset($v['expiry'])?$v['expiry']:600)),'cooldown'=>max(30,absint(isset($v['cooldown'])?$v['cooldown']:60)),'max_resends'=>max(1,absint(isset($v['max_resends'])?$v['max_resends']:3)),'max_attempts'=>max(1,absint(isset($v['max_attempts'])?$v['max_attempts']:5)),'cod'=>isset($v['cod'])?'yes':'no','login'=>isset($v['login'])?'yes':'no','registration'=>isset($v['registration'])?'yes':'no');$this->log('Settings saved api_key='.($secret?'configured':'missing').' template='.$clean['template'].' language='.$clean['language'].' checkout='.$clean['cod'].' login='.$clean['login'].' registration='.$clean['registration']);return $clean;}
	public function settings_html(){
		$s=$this->settings();$status=get_option(self::STATUS_OPTION,array());$key_hash=hash('sha256',preg_replace('/^Basic\s+/i','',trim($s['secret'])));?>
		<div class="wrap"><h1>ZARP WhatsApp OTP</h1><?php settings_errors(self::OPTION);?>
		<p>Customers enter only 10 digits. The same approved Interakt authentication template is used for checkout and account authentication, with isolated OTP purposes.</p>
		<?php if(!empty($status['ok'])&&!empty($status['key_hash'])&&hash_equals($status['key_hash'],$key_hash)):?><div class="notice notice-success inline"><p><strong>Interakt connection confirmed.</strong> <?php echo esc_html($status['message']);?><?php if(!empty($status['id'])):?> Message ID: <code><?php echo esc_html($status['id']);?></code><?php endif;?>. Confirmed <?php echo esc_html(human_time_diff((int)$status['time'],time()));?> ago.</p></div><?php elseif(!empty($s['secret'])):?><div class="notice notice-warning inline"><p><strong>API key saved; connection not confirmed yet.</strong> Request one OTP to confirm it.</p></div><?php endif;?>
		<form method="post" action="options.php"><?php settings_fields('zarp_otp');?><table class="form-table">
		<tr><th>Interakt API Key</th><td><input type="password" name="<?php echo self::OPTION;?>[secret]" value="<?php echo esc_attr($s['secret']);?>" class="regular-text" autocomplete="new-password"><p class="description">API Key from Interakt Developer Settings. The required Basic prefix is added automatically.</p></td></tr>
		<tr><th>Template / language</th><td><input name="<?php echo self::OPTION;?>[template]" value="<?php echo esc_attr($s['template']);?>"> <input name="<?php echo self::OPTION;?>[language]" value="<?php echo esc_attr($s['language']);?>"></td></tr>
		<tr><th>Expiry / cooldown seconds</th><td><input type="number" name="<?php echo self::OPTION;?>[expiry]" value="<?php echo esc_attr($s['expiry']);?>"> <input type="number" name="<?php echo self::OPTION;?>[cooldown]" value="<?php echo esc_attr($s['cooldown']);?>"></td></tr>
		<tr><th>Limits</th><td>Resends <input type="number" name="<?php echo self::OPTION;?>[max_resends]" value="<?php echo esc_attr($s['max_resends']);?>"> Attempts <input type="number" name="<?php echo self::OPTION;?>[max_attempts]" value="<?php echo esc_attr($s['max_attempts']);?>"></td></tr>
		<tr><th>Features</th><td><p><label><input type="checkbox" name="<?php echo self::OPTION;?>[cod]" <?php checked($s['cod'],'yes');?>> Checkout OTP for all payment methods</label></p><p><label><input type="checkbox" name="<?php echo self::OPTION;?>[login]" <?php checked($s['login'],'yes');?>> Enable WhatsApp OTP Login</label></p><p><label><input type="checkbox" name="<?php echo self::OPTION;?>[registration]" <?php checked($s['registration'],'yes');?>> Enable WhatsApp OTP Registration</label></p></td></tr>
		</table><?php submit_button();?></form>
		<h2>Activity log</h2><p><a class="button" href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=zarp_otp_download_log'),'zarp_otp_download_log'));?>">Download ZARP OTP activity log</a></p><p class="description">Records checkout and account authentication activity. Phone numbers are masked; OTPs, passwords and API keys are never stored.</p></div><?php
	}
}
register_activation_hook(__FILE__,array('ZARP_WhatsApp_OTP','activate')); add_action('plugins_loaded',array('ZARP_WhatsApp_OTP','instance'),20);
